    31  static void rtpin_reset(GF_RTPIn *ctx, Bool is_finalized)
    32  {
    33          while (gf_list_count(ctx->streams)) {
    34                  GF_RTPInStream *st = (GF_RTPInStream *)gf_list_get(ctx->streams, 0);
    35                  gf_list_rem(ctx->streams, 0);
    36                  if (!is_finalized && st->opid) gf_filter_pid_remove(st->opid);
    37                  rtpin_stream_del(st);
    38          }
    39
    40          rtpin_rtsp_del(ctx->session);
    41          ctx->session = NULL;
    42
    43          if (ctx->iod_desc) gf_odf_desc_del(ctx->iod_desc);
    44          ctx->iod_desc = NULL;
