    47  static GF_FilterProbeScore rtpin_probe_url(const char *url, const char *mime)
    48  {
    49          /*embedded data - TO TEST*/
    50          if (strstr(url, "data:application/mpeg4-od-au;base64")
    51                  || strstr(url, "data:application/mpeg4-bifs-au;base64")
    52                  || strstr(url, "data:application/mpeg4-es-au;base64"))
    53          {
    54                  return GF_FPROBE_SUPPORTED;
    55          }
    56
    57          /*we need rtsp/tcp , rtsp/udp or direct RTP sender (no control)*/
    58          if (!strnicmp(url, "rtsp://", 7)
    59                  || !strnicmp(url, "rtspu://", 8)
    60                  || !strnicmp(url, "rtsph://", 8)
    61                  || !strnicmp(url, "rtsps://", 8)
    62                  || !strnicmp(url, "rtp://", 6)
    63                  || !strnicmp(url, "satip://", 8))
    64          {
    65                  return GF_FPROBE_SUPPORTED;
    66          }
    67
    68          return GF_FPROBE_NOT_SUPPORTED;
    69  }
