    71  //simplified version of RTSP_UnpackURL for SAT>IP
    72  void rtpin_satip_get_server_ip(const char *sURL, char *Server)
    73  {
    74          char schema[10], *test, text[1024], *retest;
    75          u32 i, len;
    76          Bool is_ipv6;
    77          if (!sURL) return;
    78
    79          strcpy(Server, "");
    80
    81          //extract the schema
    82          i = 0;
    83          while (i <= strlen(sURL)) {
    84                  if (sURL[i] == ':')
    85                          goto found;
    86                  schema[i] = sURL[i];
    87                  i += 1;
    88          }
    89          return;
    90
    91  found:
    92          schema[i] = 0;
    93          if (stricmp(schema, "satip")) {
    94                  GF_LOG(GF_LOG_ERROR, GF_LOG_RTP, ("[RTP] Wrong SATIP schema %s - not setting up\n", schema));
    95                  return;
    96          }
    97          test = strstr(sURL, "://");
    98          test += 3;
    99
   100          //check for port
   101          retest = strrchr(test, ':');
   102          /*IPV6 address*/
   103          if (retest && strchr(retest, ']')) retest = NULL;
   104
   105          if (retest && strstr(retest, "/")) {
   106                  retest += 1;
   107                  i = 0;
   108                  while (i<strlen(retest)) {
   109                          if (retest[i] == '/') break;
   110                          text[i] = retest[i];
   111                          i += 1;
   112                  }
   113                  text[i] = 0;
   114          }
   115          //get the server name
   116          is_ipv6 = GF_FALSE;
   117          len = (u32)strlen(test);
   118          i = 0;
   119          while (i<len) {
   120                  if (test[i] == '[') is_ipv6 = GF_TRUE;
   121                  else if (test[i] == ']') is_ipv6 = GF_FALSE;
   122                  if ((test[i] == '/') || (!is_ipv6 && (test[i] == ':'))) break;
   123                  text[i] = test[i];
   124                  i += 1;
   125          }
   126          text[i] = 0;
   127          strcpy(Server, text);
   128  }
