   777  static GF_Err rtpin_initialize(GF_Filter *filter)
   778  {
   779          GF_RTPIn *ctx = gf_filter_get_udta(filter);
   780          char *the_ext;
   781
   782          ctx->streams = gf_list_new();
   783          ctx->filter = filter;
   784          //turn on interleave on http port
   785          if (ctx->transport==RTP_TRANSPORT_AUTO) {
   786                  if ((ctx->default_port == 80) || (ctx->default_port == 8080))
   787                          ctx->transport = RTP_TRANSPORT_TCP_ONLY;
   788                  if (ctx->src && !strnicmp(ctx->src, "rtsph://", 8))
   789                          ctx->transport = RTP_TRANSPORT_TCP_ONLY;
   790          }
   791
   792          ctx->last_start_range = -1.0;
   793
   794          ctx->sockgroup = gf_sk_group_new();
   795          //prevent blocking so that we are always called even if output is full
   796          gf_filter_prevent_blocking(filter, GF_TRUE);
   797
   798          //sdp mode, we will have a configure_pid
   799          if (!ctx->src) return GF_OK;
   800
   801          /*rtsp and rtsp over udp*/
   802
   803          the_ext = strrchr(ctx->src, '#');
   804          if (the_ext) {
   805                  if (!stricmp(the_ext, "#audio")) ctx->stream_type = GF_STREAM_AUDIO;
   806                  else if (!stricmp(the_ext, "#video")) ctx->stream_type = GF_STREAM_VISUAL;
   807                  the_ext[0] = 0;
   808          }
   809          gf_filter_disable_inputs(filter);
   810
   811          if (!strnicmp(ctx->src, "rtp://", 6)) {
   812                  GF_RTPInStream *stream;
   813                  GF_Err e = GF_OK;
   814                  u32 port = 1234;
   815                  char *ip = ctx->src + 6;
   816                  char *sep = strchr(ip, ':');
   817                  if (sep) {
   818                          port = atoi(sep+1);
   819                          sep[0] = 0;
   820                          ip = gf_strdup(ip);
   821                          sep[0] = ':';
   822                  } else {
   823                          ip = gf_strdup(ip);
   824                  }
   825                  stream = rtpin_stream_new_standalone(ctx, ip, port, GF_FALSE);
   826                  gf_free(ip);
   827                  if (!stream)
   828                          e = GF_OUT_OF_MEM;
   829
   830                  if (!e)
   831                          e = rtpin_add_stream(ctx, stream, NULL);
   832
   833                  if (!e)
   834                          e = rtpin_stream_init(stream, GF_FALSE);
   835
   836                  if (e) {
   837                          GF_LOG(GF_LOG_ERROR, GF_LOG_RTP, ("[RTPIn]] Couldn't setup RTP stream: %s\n", gf_error_to_string(e) ));
   838                          return e;
   839                  }
   840                  stream->status = RTP_Running;
   841                  return GF_OK;
   842          }
   843          ctx->session = rtpin_rtsp_new(ctx, (char *) ctx->src);
   844          if (!ctx->session)
   845                  return GF_NOT_SUPPORTED;
   846
   847          if (!strnicmp(ctx->src, "satip://", 8)) {
   848                  ctx->session->satip = GF_TRUE;
   849                  ctx->session->satip_server = gf_malloc(GF_MAX_PATH);
   850                  rtpin_satip_get_server_ip(ctx->src, ctx->session->satip_server);
   851          }
   852
   853          ctx->dm = gf_filter_get_download_manager(filter);
   854          if (!strnicmp(ctx->src, "rtsps://", 8)
   855                  || (!strnicmp(ctx->src, "rtsph://", 8) &&
   856                          ((gf_rtsp_get_session_port(ctx->session->session) == 443) || (gf_rtsp_get_session_port(ctx->session->session) == 8443)))
   857          ) {
   858  #ifdef GPAC_HAS_SSL
   859
   860  #ifdef GPAC_ENABLE_COVERAGE
   861                  //all our tests directly detect ssl from above conditions
   862                  if (gf_sys_is_cov_mode())
   863                          gf_rtsp_session_needs_ssl(ctx->session->session);
   864  #endif
   865
   866                  GF_Err e = gf_rtsp_set_ssl_ctx(ctx->session->session, gf_dm_ssl_init(ctx->dm, 0) );
   867                  if (e) return e;
   868  #else
   869                  return GF_NOT_SUPPORTED;
   870  #endif
